]=60,[\"angle\"]=3.141592653589793},[34438]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34440]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34441]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34404]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34429]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34422]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34430]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34439]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8},[34442]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8}} end\nlocal s=data.jacobRokkon\nif not s.goraiHelpers then\n    s.goraiHelpers=true\n    function s.gTower(t)\n        local p=TensorCore.mGetPlayer()\n        if not p or not s.gTowerMode or s.gTowerMode~=1 then return end\n        local blue=t.index%2==0\n        local order=blue and s.gBlueOrder or s.gOrangeOrder\n        if order~=t.wave then return end\n        t.mine=true\n        s.own(s.green:addTimedCircle(t.deadline-Now(),t.pos.x,t.pos.y,t.pos.z,3.3,0,false,true),t.deadline)\n        s.timer(t.deadline-Now(),t.pos,0xFF33FF33)\n        if not s.gMyTower or t.wave<s.gMyTower.wave then s.gMyTower=t end\n        s.call((t.wave>s.gResolvedWave+1 and \"Next: \" or \"\")..(blue and \"Blue tower\" or \"Orange tower\"),false)\n        if s.gMyTower==t then s.guideTo(t.pos,t.deadline,\"gorai-tower-\"..t.wave) end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.mokoHelpers then\n    s.mokoHelpers=true\n    function s.tripleStep(v,pos,heading,inside,deadline)\n        if v.shapes then for _,u in ipairs(v.shapes) do s.remove(u) end end\n        v.pos=pos;v.heading=heading;v.deadline=deadline;v.inside=inside\n        local cone=s.add({kind=\"cone\",pos=pos,r=60,angle=math.pi*1.5,heading=heading,deadline=deadline,caster=v.boss,noTimer=true})\n        local radial=s.add({kind=inside and \"donut\" or \"circle\",pos=pos,inner=6,r=inside and 40 or 6,deadline=deadline,caster=v.boss,noTimer=true})\n        v.shapes={cone.uuid,radial.uuid}\n        s.timer(math.max(1,deadline-Now()),pos)\n        local h=heading+math.pi\n        local r=inside and 3.5 or 8\n        s.clearGuide()\n        s.guideTo({x=pos.x+r*math.sin(h),y=pos.y,z=pos.z+r*math.cos(h)},deadline,\"triple-\"..v.index)\n        if v.called~=v.index then s.call((inside and \"IN\" or \"OUT\")..\": green wedge\",false);v.called=v.index end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.shishioHelpers then\n    s.shishioHelpers=true;s.clouds={};s.cloudForecast={};s.breaths=0;s.rings={}\n    function s.cloudChain(line)\n        local radius=({8,12,23})[s.breaths]\n        if not radius then return end\n        local times={}\n        for id,c in pairs(s.clouds) do\n            local dx,dz=c.pos.x-line.pos.x,c.pos.z-line.pos.z\n            local along=dx*math.sin(line.heading)+dz*math.cos(line.heading)\n            local across=dx*math.cos(line.heading)-dz*math.sin(line.heading)\n            if math.abs(along)<=30 and math.abs(across)<=7 then times[id]=line.deadline+1100 end\n        end\n        for _=1,32 do\n            local changed=false\n            for id,c in pairs(s.clouds) do\n                if times[id] then\n                    for other,d in pairs(s.clouds) do\n                        if other~=id and (c.pos.x-d.pos.x)^2+(c.pos.z-d.pos.z)^2<=radius^2 then\n                            local t=times[id]+1100\n                            if not times[other] or t<times[other] then times[other]=t;changed=true end\n                        end\n                    end\n                end\n            end\n            if not changed then break end\n        end\n        for id,deadline in pairs(times) do\n            local old=s.cloudForecast[id]\n            if not old or deadline<old.deadline then\n                if old then s.remove(old.uuid);old.deadline=0 end\n                local c=s.clouds[id]\n                local h=s.add({kind=\"circle\",pos=c.pos,r=radius,start=deadline-1100,deadline=deadline,\n                    caster=id,cloud=true,noTimer=true})\n                s.cloudForecast[id]=h\n            end\n        end\n    end\n    function s.nobleRing(pos,h)\n        local last=s.charges and s.charges[#s.charges]\n        if not last then\n            s.noblePending=s.noblePending or{};s.noblePending[#s.noblePending+1]={pos=pos,heading=h};return\n        end\n        if not s.danger(last,pos.x,pos.z) then\n            local from=s.nobleEnd\n            local dx,dz=pos.x-from.x,pos.z-from.z\n            if math.abs(dx)<.1 then dx=0 end\n            if math.abs(dz)<.1 then dz=0 end\n            local len=math.sqrt(dx*dx+dz*dz)\n            if len<.1 then return end\n            local ux,uz=dx/len,dz/len\n            local tx=math.abs(ux)>.001 and ((ux>0 and 20 or -20)-from.x)/ux or math.huge\n            local tz=math.abs(uz)>.001 and ((uz>0 and -80 or -120)-from.z)/uz or math.huge\n            local length=math.min(tx,tz)\n            if length<=0 or length>60 then return end\n            last=s.add({kind=\"rect\",pos=from,length=length,width=12,heading=TensorCore.getHeadingToTarget(from,pos),\n                start=last.deadline,deadline=last.deadline+1400,noTimer=true,noble=true})\n            s.charges[#s.charges+1]=last\n            s.nobleEnd={x=from.x+ux*length,y=from.y,z=from.z+uz*length}\n        end\n        s.add({kind=\"centered\",pos=pos,length=10,width=100,heading=h,start=last.deadline,\n            deadline=last.deadline+800,noTimer=true,noble=true})\n    end\nend\n\nlocal s=data.jacobRokkon\nlocal now=Now()\nif not jacobRokkonOptions.enabled then s.cleanup();self.used=true;return end\nlocal p=TensorCore.mGetPlayer()\nif not p then return end\nif s.activeBossID then\n    local boss=TensorCore.mGetEntity(s.activeBossID)\n    if boss and not boss.alive then s.cleanup();s.activeBossID=nil;s.activeBoss=nil;self.used=true;return end\nend\nif s.statusReadUntil then\n    if now>s.statusReadUntil then s.statusReadUntil=nil;s.statusReadAt=nil\n    elseif now>=s.statusReadAt then\n        for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n            for _,id in ipairs(s.statusIDs) do\n                local b=TensorCore.getBuff(e,id)\n                if b and b.duration>0 then\n                    local deadline=now+b.duration*1000\n                    if id==3563 or id==3608 or id==3610 then s.spreads[e.id]=deadline\n                    else s.stacks[e.id]=deadline;s.stackDeadline=deadline end\n                end\n            end\n        end\n        s.statusReadAt=now+250\n    end\nend\nif s.gOrderReadUntil then\n    if now>s.gOrderReadUntil or s.gOrangeOrder and s.gBlueOrder then s.gOrderReadUntil=nil\n    elseif now>=(s.gOrderReadAt or 0) then\n        for id=3597,3604 do\n            local b=TensorCore.getBuff(p,id)\n            if b and b.duration>0 then\n                if id<=3600 then s.gOrangeOrder=id-3596 else s.gBlueOrder=id-3600 end\n            end\n        end\n        for _,t in ipairs(s.gTowers or {}) do if not t.mine then s.gTower(t) end end\n        s.gOrderReadAt=now+250\n    end\nend\ns.statusDraws(now)\nif s.gazeUntil then\n    if now>=s.gazeUntil or not jacobRokkonOptions.gaze then\n        TensorCore.API.TensorACR.toggleLockFace(false)\n        TensorCore.API.TensorACR.setHardLockFace(false)\n        s.gazeUntil=nil\n    elseif now>=s.gazeAt then\n        local e=TensorCore.mGetEntity(s.gazeSource)\n        if e then\n            TensorCore.API.TensorACR.setLockFaceHeading((TensorCore.getHeadingToTarget(p.pos,e.pos)+math.pi)%(2*math.pi))\n            TensorCore.API.TensorACR.setHardLockFace(true)\n            TensorCore.API.TensorACR.toggleLockFace(true)\n        end\n    end\nend\nif s.towerGatherAt and now>=s.towerGatherAt and not s.towerAssigned and #s.towers==2 then\n    local marked,players=0,{}\n    for _,deadline in pairs(s.largeSpreads or {}) do if deadline>now then marked=marked+1 end end\n    if marked==2 then\n        for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n            if e.alive and not (s.largeSpreads and s.largeSpreads[e.id] and s.largeSpreads[e.id]>now) then players[#players+1]=e end\n        end\n        if #players==2 then\n            table.sort(players,function(a,b)\n                local ar,br=s.role(a),s.role(b)\n                return ar==br and a.id<b.id or ar<br\n            end)\n            local a,b=s.towers[1],s.towers[2]\n            local function distance(e,t) return math.sqrt((e.pos.x-t.pos.x)^2+(e.pos.z-t.pos.z)^2) end\n            if jacobRokkonOptions.towerMode==1 then\n                if distance(players[1],b)+distance(players[2],a)<distance(players[1],a)+distance(players[2],b) then a,b=b,a end\n            elseif jacobRokkonOptions.towerMode==2 then\n                local center={x=0,y=0,z=-100}\n                local ah=(TensorCore.getHeadingToTarget(center,a.pos)+math.pi)%(2*math.pi)\n                local bh=(TensorCore.getHeadingToTarget(center,b.pos)+math.pi)%(2*math.pi)\n                if bh<ah then a,b=b,a end\n            end\n            if jacobRokkonOptions.towerMode~=3 then\n                s.towerAssigned=true\n                if players[1].id==p.id then s.myTower=a elseif players[2].id==p.id then s.myTower=b end\n                if s.myTower then\n                    local t=s.myTower\n                    s.own(s.green:addTimedCircle(t.deadline-now,t.pos.x,t.pos.y,t.pos.z,3.3,0,false,true),t.deadline)\n                    s.timer(t.deadline-now,t.pos,0xFF33FF33)\n                    s.call(\"Next: your green tower\",false)\n                end\n            else s.towerAssigned=true;s.call(\"Unmarked: soak a tower\",false) end\n        end\n    end\nend\nif s.towerGatherAt and s.towers[1] and now>=s.towers[1].deadline then\n    s.towerGatherAt=nil;s.myTower=nil;s.towers={};s.towerAssigned=nil;s.towerCalled=nil\nend\nfor u,deadline in pairs(s.shapes) do if now>=deadline then s.remove(u) end end\nfor i=#s.hazards,1,-1 do if now>=s.hazards[i].deadline then table.remove(s.hazards,i) end end\nif s.eye and now>=s.eye.first then\n    local v=s.eye\n    if not v.advanced then\n        v.advanced=true\n        s.clearGuide()\n        s.add({kind=v.out and \"donut\" or \"circle\",pos=v.pos,r=v.out and 30 or 15,inner=8,\n            deadline=v.second,caster=v.caster,spell=v.out and 33812 or 33814})\n        s.call(v.out and \"Move IN\" or \"Move OUT\",false)\n        s.eyeSpot()\n    end\n    if now>=v.second then s.eye=nil end\nend\nlocal forecastTime,forecastType\nif s.cloudGuideUntil or s.nobleGuideUntil then\n    for _,h in ipairs(s.hazards) do\n        if (h.cloud and s.cloudGuideUntil or h.noble and s.nobleGuideUntil) and h.deadline>now then\n            if not forecastTime or h.deadline<forecastTime then forecastTime=h.deadline;forecastType=h.cloud and \"cloud\" or \"noble\" end\n        end\n    end\n    if not forecastTime then s.cloudGuideUntil=nil;s.nobleGuideUntil=nil end\nend\nlocal exaTime\nif s.exaUntil and now<s.exaUntil then\n    for _,h in ipairs(s.hazards) do if h.exa and h.deadline>now and (not exaTime or h.deadline<exaTime) then exaTime=h.deadline end end\nelseif s.exaUntil then s.exaUntil=nil;s.exaCenter=nil end\nif s.myGhost then\n    local e=TensorCore.mGetEntity(s.myGhost)\n    if e then\n        s.ghostLastSeen=now\n        if not s.ghostHeading then s.ghostHeading=(TensorCore.getHeadingToTarget({x=0,y=e.pos.y,z=-100},e.pos)+math.pi)%(2*math.pi) end\n        if not s.ghostRotate and e.pos.x^2+(e.pos.z+100)^2<25 then\n            s.ghostRotate=true;s.call(\"Rotate clockwise\",false)\n        end\n        local h=s.ghostHeading\n        if s.ghostRotate then h=TensorCore.getHeadingToTarget({x=0,y=p.pos.y,z=-100},p.pos)-math.pi/7 end\n        local x,z=18*math.sin(h),18*math.cos(h)\n        if not s.circleArena then\n            local scale=18/math.max(math.abs(x),math.abs(z))\n            x=x*scale;z=z*scale\n        end\n        s.guideTo({x=x,y=p.pos.y,z=-100+z},now+1000,\"ghost-kite\")\n    elseif s.ghostLastSeen and now-s.ghostLastSeen>1000 then s.myGhost=nil;s.clearGuide() end\nelseif s.hammerUntil and now<s.hammerUntil and s.hammerOrb then\n    if s.hammerTarget==p.id then s.guideTo(s.hammerOrb,s.hammerUntil,\"hammer-orb\")\n    else\n        local r=s.role()\n        local h=TensorCore.getHeadingToTarget(s.hammerOrb,{x=300,y=p.pos.y,z=-120})\n        if r==1 then h=h else h=h+math.pi/2 end\n        local d=r==1 and 5 or 7\n        s.guideTo({x=s.hammerOrb.x+d*math.sin(h),y=p.pos.y,z=s.hammerOrb.z+d*math.cos(h)},s.hammerUntil,\"hammer-avoid\")\n    end\nelseif s.flameUntil and now<s.flameUntil then\n    if s.guide and s.guide.key==\"flame\" and s.safe(s.guide.pos.x,s.guide.pos.z,s.flameUntil) then\n        s.guideTo(s.guide.pos,s.flameUntil,\"flame\")\n        self.used=true;return\n    end\n    local north=s.role()==1 or s.role()==2\n    local countN,countS=0,0\n    for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n        if s.stacks[e.id] and s.stacks[e.id]>now then\n            local r=s.role(e)\n            if r==1 or r==2 then countN=countN+1 else countS=countS+1 end\n        end\n    end\n    if (countN==2 or countS==2) and (s.role()==2 or s.role()==3) then north=not north end\n    local best,score\n    for x=282,318,1 do\n        for z=north and -138 or -119,north and -121 or -102,1 do\n            if s.safe(x,z,s.flameUntil) then\n                local d=(x-p.pos.x)^2+(z-p.pos.z)^2\n                if not score or d<score then score=d;best={x=x,y=p.pos.y,z=z} end\n            end\n        end\n    end\n    if best then s.guideTo(best,s.flameUntil,\"flame\") end\nelseif s.myTower and now<s.myTower.deadline and not s.myGhost then\n    if not s.towerCalled then s.towerCalled=true;s.call(\"Soak your tower\",false) end\n    s.guideTo(s.myTower.pos,s.myTower.deadline,\"personal-tower\")\nelseif forecastTime then\n    local stage=forecastType..math.floor(forecastTime/500)\n    s.avoid(forecastTime,{x=0,z=-100},s.cloudGuideUntil and 19 or 20,stage)\n    if s.cloudStage~=stage then\n        s.cloudStage=stage;s.call(forecastType=='cloud' and 'Green gap, then follow the cleared space' or 'Dodge into the green gap',false)\n    end\nelseif s.triple and s.triple.deadline and now<s.triple.deadline then\n    local v=s.triple\n    local radius=v.inside and 3.5 or 8\n    local h=v.heading+math.pi\n    s.guideTo({x=v.pos.x+radius*math.sin(h),y=v.pos.y,z=v.pos.z+radius*math.cos(h)},v.deadline,\"triple-\"..v.index)\nelseif exaTime then s.avoid(exaTime,s.exaCenter,20,\"exa-\"..math.floor(exaTime/500))\nelseif s.eye then s.eyeSpot()\nelseif s.avoidUntil then\n    if now<s.avoidUntil then s.avoid(s.avoidUntil,s.avoidCenter,20,s.avoidKey)\n    else s.avoidUntil=nil;s.clearGuide() end\nelseif s.guide then\n    if now>=s.guide.deadline then s.clearGuide()\n    else s.guideTo(s.guide.pos,s.guide.deadline,s.guide.key) end\nend\nself.used=true\n",
